const filterNullValues = <D extends BarDatum>(data: D) =>
    Object.keys(data).reduce<Record<string, unknown>>((acc, key) => {
        if (data[key]) {
            acc[key] = data[key]
        }
        return acc
    }, {}) as Exclude<D, null | undefined | false | '' | 0>;
